"""Build the static studio and POPORA support pages. No runtime dependencies."""
from pathlib import Path
import json
from html import escape
from urllib.parse import quote
root=Path(__file__).resolve().parent.parent
brand='''<span class="brand"><svg viewBox="0 0 36 42" fill="none" aria-hidden="true"><path d="M4 35V17a14 14 0 0 1 28 0v18" stroke="currentColor" stroke-width="5" stroke-linecap="round"/><path d="M4 25h28M14 35h8" stroke="currentColor" stroke-width="5" stroke-linecap="round"/></svg><span>ANSHIN<small>LABS</small></span></span>'''
def header(prefix='',legal=False):
 return f'''<a class="skip" href="#main" data-i18n="skip">본문으로 바로가기</a><header class="header wrap"><a href="{prefix}index.html" data-lang-link="{prefix}index.html" aria-label="ANSHIN LABS">{brand}</a><nav aria-label="Main"><a href="{prefix}index.html#games" data-lang-link="{prefix}index.html#games" data-i18n="games">게임</a><a class="studio-nav" href="{prefix}index.html#studio" data-lang-link="{prefix}index.html#studio" data-i18n="studio">스튜디오</a><a href="{prefix}index.html#support" data-lang-link="{prefix}index.html#support" data-i18n="support">고객지원</a><select data-language aria-label="언어"><option value="ko">한국어</option><option value="ja">日本語</option><option value="en">English</option></select></nav></header>'''
def footer():return '''<footer class="footer wrap"><span>ANSHIN LABS</span><span data-i18n="footer">작은 세계, 큰 모험.</span><span>© 2026 anshin-labs</span></footer>'''
def doc(title,body,canonical,prefix='',page='home',script='site.js'):
 return f'''<!doctype html>
<html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><meta name="description" content="동물구조대와 포포라. ANSHIN LABS의 게임과 고객지원 안내를 만나보세요."><meta name="theme-color" content="#f8f7f1"><meta property="og:title" content="{title}"><meta property="og:description" content="Little friends. Big adventures. Meet the games of ANSHIN LABS."><meta property="og:type" content="website"><meta property="og:image" content="https://anshin-labs.com/assets/popora-world.webp"><meta property="og:url" content="https://anshin-labs.com/{canonical}"><link rel="canonical" href="https://anshin-labs.com/{canonical}"><link rel="icon" href="{prefix}assets/studio-mark.svg" type="image/svg+xml"><link rel="stylesheet" href="{prefix}site.css"><script defer src="{prefix}{script}"></script></head><body data-page="{page}">{body}</body></html>'''
def support_links(game):
 if game=='animal':return '''<a data-mail-game="Animal Rescue" href="mailto:info@anshin-labs.com?subject=Animal%20Rescue" data-i18n="contact">문의하기</a><a href="privacy.html" data-lang-link="privacy.html" data-i18n="privacy">개인정보처리방침</a><a href="delete-account.html" data-lang-link="delete-account.html" data-i18n="deletion">계정 삭제 안내</a>'''
 return '''<a href="popora/support.html" data-lang-link="popora/support.html" data-i18n="contact">문의하기</a><a href="popora/privacy.html" data-lang-link="popora/privacy.html" data-i18n="privacy">개인정보처리방침</a><a href="popora/delete-account.html" data-lang-link="popora/delete-account.html" data-i18n="deletion">계정 삭제 안내</a>'''
card=''
for slug,name in [('animal','animal'),('popora','popora')]:
 href='animal-rescue.html' if slug=='animal' else 'popora/'
 title='도와줘요! 동물구조대' if slug=='animal' else '포포라: 노모 군단'
 image='animal-world.webp' if slug=='animal' else 'popora-world.webp'
 desc='퍼즐을 풀고, 사랑스러운 동물 친구들을 구해 주세요.' if slug=='animal' else '병사를 모으고 합성해 나만의 노모 군단을 만드세요.'
 status='<span class="status" data-i18n="platform">iOS · Android</span>' if slug=='animal' else '<span class="status soon" data-i18n="soon">출시 준비 중</span>'
 card+=f'''<article class="game-card"><a class="game-art {slug}-art" href="{href}" data-lang-link="{href}"><img src="assets/{image}" width="{'672' if slug=='animal' else '1440'}" height="{'1536' if slug=='animal' else '960'}" alt="{title}" data-i18n-alt="{name}Art" fetchpriority="high"><span class="number">0{'1' if slug=='animal' else '2'} / ANSHIN LABS</span></a><div class="card-content"><div class="game-title"><img src="assets/{slug}-icon.webp" width="54" height="54" alt=""><div><p class="genre" data-i18n="{name}Genre">{'퍼즐 · 동물 구출' if slug=='animal' else '전략 · 수집 · 대전'}</p><h3 data-i18n="{name}Name">{title}</h3></div></div><p class="game-description" data-i18n="{name}Desc">{desc}</p><div class="card-bottom">{status}<a class="text-link" href="{href}" data-lang-link="{href}"><span data-i18n="details">게임 살펴보기</span><span class="arrow" aria-hidden="true">↗</span></a></div></div></article>'''
body=header()+f'''<main id="main" class="wrap"><section class="hero"><div><p class="eyebrow" data-i18n="eyebrow">기분 좋은 모험을 만드는 게임 스튜디오</p><h1><span data-i18n="hero1">작은 친구들과,</span><span data-i18n="hero2">더 큰 모험.</span></h1></div><div class="hero-side"><p data-i18n="intro">동물 친구를 구하는 포근한 퍼즐부터\n작은 노모들이 펼치는 커다란 전투까지.</p><a class="text-link" href="#games"><span data-i18n="explore">우리의 게임 만나기</span><span class="arrow" aria-hidden="true">↓</span></a></div></section><section id="games" class="games"><div class="section-top"><h2 data-i18n="gamesTitle">어떤 모험을 떠나볼까요?</h2><p data-i18n="gamesNote">서로 다른 즐거움. 같은 따뜻한 마음.</p></div><div class="game-grid">{card}</div></section><section id="studio" class="studio"><div><p class="eyebrow" data-i18n="studioLabel">우리의 이야기</p><h2 data-i18n="studioTitle">오래 기억할\n작은 즐거움.</h2></div><div class="studio-copy"><p data-i18n="studioText">ANSHIN LABS는 개성 있는 친구들과 다시 찾아오고 싶은 세계를 만듭니다. 가볍게 시작해서, 나만의 방식으로 오래 즐기는 게임을 전합니다.</p><span class="signoff" data-i18n="studioEnd">만나서 반가워요. 함께 놀아요.</span></div></section><section id="support" class="support"><div class="support-intro"><p class="eyebrow">PLAYER SUPPORT</p><h2 data-i18n="supportTitle">무엇을 도와드릴까요?</h2><p data-i18n="supportText">궁금한 점이나 도움이 필요한 일이 있다면, 플레이 중인 게임을 선택해 주세요.</p></div><div class="support-grid"><article class="support-card"><h3 data-i18n="animalName">도와줘요! 동물구조대</h3><div class="support-links">{support_links('animal')}</div></article><article class="support-card"><h3 data-i18n="poporaName">포포라: 노모 군단</h3><div class="support-links">{support_links('popora')}</div></article></div><div class="mail-row"><a href="mailto:info@anshin-labs.com">info@anshin-labs.com ↗</a><p data-i18n="supportHint">문의할 때 게임 이름과 유저 ID를 함께 적어 주세요. 비밀번호는 보내지 마세요.</p></div></section></main>'''+footer()
(root/'index.html').write_text(doc('ANSHIN LABS — 작은 친구들과, 더 큰 모험',body,''))
features=''
for slug,title in [('legion','나만의 군단'),('towers','타워 점령전'),('tribes','노모 부족전')]:
 features+=f'''<article><img src="../assets/popora-{slug}.webp" width="1000" height="667" loading="lazy" alt="{title}" data-i18n-alt="{slug}Title"><h3 data-i18n="{slug}Title">{title}</h3><p data-i18n="{slug}Text"></p></article>'''
body=header('../')+f'''<main id="main" class="wrap"><section class="detail-hero"><a class="back-link" href="../index.html#games" data-lang-link="../index.html#games">← <span data-i18n="back">게임 목록으로</span></a><div class="detail-heading"><div><p class="eyebrow" data-i18n="poporaGenre">전략 · 수집 · 대전</p><h1 data-i18n="poporaName">포포라: 노모 군단</h1><p data-i18n="poporaLead">나만의 노모 군단을 이끌고,\n더 큰 세계로.</p></div><div class="detail-intro"><p data-i18n="poporaIntro">수집하고, 합치고, 배치하세요. 귀여운 노모들의 조합이 새로운 전략이 됩니다.</p><span class="status soon" data-i18n="releaseNote">iOS와 Android 출시를 준비하고 있습니다.</span></div></div><div class="detail-cover"><img src="../assets/popora-world.webp" width="1440" height="960" alt="노모 군단의 판타지 전투" data-i18n-alt="poporaArt"><span class="art-caption" data-i18n="illustration">게임 세계를 표현한 일러스트</span></div></section><section class="detail-features"><h2 data-i18n="poporaFeatures">작은 노모들이 만드는 큰 이야기</h2><div class="feature-grid">{features}</div></section><section class="detail-support"><h2 data-i18n="poporaSupport">포포라 도움이 필요하신가요?</h2><p data-i18n="poporaSupportText">계정 연결, 저장 기록, 구매, 계정 삭제에 대한 안내를 확인하세요.</p><div class="support-links"><a href="support.html" data-lang-link="support.html" data-i18n="contact">문의하기</a><a href="privacy.html" data-lang-link="privacy.html" data-i18n="privacy">개인정보처리방침</a><a href="delete-account.html" data-lang-link="delete-account.html" data-i18n="deletion">계정 삭제 안내</a></div></section></main>'''+footer()
(root/'popora/index.html').write_text(doc('POPORA: NOMO Legion — ANSHIN LABS',body,'popora/',prefix='../',page='popora'))
# POPORA's reviewed support/privacy wording is kept verbatim in all ten locales.
copy=json.loads((root/'popora/support-copy.json').read_text())
def legal_fallback(page,c):
 # Keep support instructions readable before JavaScript runs or in text browsers.
 def p(i):return '<p>'+escape(c[i])+'</p>'
 def h(i):return '<h2>'+escape(c[i])+'</h2>'
 def a(text,url):return '<a href="'+escape(url,quote=True)+'">'+escape(text)+'</a>'
 mail='mailto:info@anshin-labs.com?subject='+quote('POPORA — '+c[8 if page=='delete-account' else 1])
 email='<p>'+a('info@anshin-labs.com',mail)+'</p>'
 deletion=a(c[22]+' →','delete-account.html?lang=ko')
 if page=='support':return h(5)+p(6)+a(c[7],mail)+email+deletion
 if page=='delete-account':return h(8)+p(9)+p(10)+a(c[13],mail)+email+'<div class="legal-notice">'+p(11)+p(12)+'</div>'
 providers=[('Supabase','https://supabase.com/privacy'),('Apple','https://www.apple.com/legal/privacy/'),('Google','https://policies.google.com/privacy'),('Google AdMob','https://policies.google.com/technologies/partner-sites')]
 return p(23)+''.join(h(i)+p(i+1) for i in [14,16,18,20])+deletion+email+'<ul>'+''.join('<li>'+a(name,url)+'</li>' for name,url in providers)+'</ul>'
for page,index in [('support',1),('privacy',3),('delete-account',2)]:
 c=copy['ko']; t=c[index]
 body=f'''<header class="header wrap"><a href="../index.html" aria-label="ANSHIN LABS">{brand}</a><select id="support-language" aria-label="Language">'''+''.join(f'<option value="{k}">{escape(v[0])}</option>' for k,v in copy.items())+'''</select></header><nav class="legal-tabs wrap" aria-label="POPORA"><a href="./">POPORA</a><a href="support.html" data-support-nav="1">고객지원</a><a href="delete-account.html" data-support-nav="2">계정 삭제</a><a href="privacy.html" data-support-nav="3">개인정보처리방침</a></nav><main id="main" class="legal-main wrap"><p class="legal-kicker">POPORA · ANSHIN LABS</p><h1>'''+escape(t)+'''</h1><div id="support-content"></div></main><footer class="footer wrap"><span>ANSHIN LABS · POPORA</span><a href="mailto:info@anshin-labs.com">info@anshin-labs.com</a><span>© 2026 anshin-labs</span></footer>'''
 html=doc(t+' · POPORA',body,'popora/'+page+'.html',prefix='../',page=page,script='popora/support.js')
 html=html.replace('<div id="support-content"></div>','<div id="support-content">'+legal_fallback(page,c)+'</div>')
 # Embed an audited, non-executable JSON payload so file/static previews need no fetch.
 html=html.replace('</head>', '<script type="application/json" id="support-copy">'+json.dumps(copy,ensure_ascii=False).replace('</','<\\/')+'</script></head>')
 (root/'popora'/f'{page}.html').write_text(html)
(root/'assets/studio-mark.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="16" fill="#345d46"/><path d="M17 47V28a15 15 0 0 1 30 0v19M17 36h30" fill="none" stroke="#f8f7f1" stroke-width="6" stroke-linecap="round"/></svg>')
print('Built index, POPORA detail and three multilingual support pages.')
